// N counts VISIBLE messages, but slug markers inside the resulting window are
// still returned. Two reasons to do it this way rather than just excluding them:
// an invisible bookkeeping row must not eat the window (?tail=1 would hand back
// nothing displayable), yet dropping markers from the middle would punch holes
// in the sequence space, and clients that detect lost messages by sequence
// contiguity (see the iOS store's firstGapBoundary) would read those holes as
// missing data and re-fetch forever.
func (q *Queries) ListMessagesTail(ctx context.Context, arg ListMessagesTailParams) ([]Message, error) {
	rows, err := q.db.QueryContext(ctx, listMessagesTail, arg.ConversationID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Message{}
	for rows.Next() {
		var i Message
		if err := rows.Scan(
			&i.MessageID,
			&i.ConversationID,
			&i.SequenceID,
			&i.Type,
			&i.LlmData,
			&i.UserData,
			&i.UsageData,
			&i.CreatedAt,
			&i.DisplayData,
			&i.ExcludedFromContext,
			&i.Generation,
			&i.LlmApiUrl,
			&i.ModelName,
			&i.ForkedFromMessageID,
			&i.UserEmail,
			&i.OtherUsageData,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateMessageUserData = `-- name: UpdateMessageUserData :exec
UPDATE messages SET user_data = ? WHERE message_id = ?
`

type UpdateMessageUserDataParams struct {
	UserData  *string `json:"user_data"`
	MessageID string  `json:"message_id"`
}

// Mutating message rows is forbidden in production paths (messages are an
// immutable, append-only log keyed by sequence_id and cached in the browser).
// This UPDATE exists ONLY for the FTS-trigger test (TestMessages*), which
// verifies the messages_fts AFTER UPDATE trigger re-indexes user_data.
func (q *Queries) UpdateMessageUserData(ctx context.Context, arg UpdateMessageUserDataParams) error {
	_, err := q.db.ExecContext(ctx, updateMessageUserData, arg.UserData, arg.MessageID)
	return err
}
